const webhookItem = items[0]?.json;
const raw = webhookItem && typeof webhookItem === 'object' && !Array.isArray(webhookItem)
  ? (webhookItem.body ?? webhookItem)
  : null;
const CONTRACT_VERSION = '1.0';
const MAX_BYTES = 256 * 1024;
const publicMessage = 'We couldn\'t prepare the diagnostic. Try again or continue with the local demo.';
function isObject(value) { return Boolean(value) && typeof value === 'object' && !Array.isArray(value); }
function nonEmpty(value) { return typeof value === 'string' && value.trim().length > 0; }
function envelope(status, correlationId, runId, extra = {}) {
  return { contract_version: CONTRACT_VERSION, status, correlation_id: correlationId, run_id: runId, demo: false, message: publicMessage, ...extra };
}
function generatedId(prefix) {
  const executionId = typeof $execution !== 'undefined' && $execution?.id ? String($execution.id) : crypto.randomUUID();
  return `${prefix}-${executionId}`;
}
function utf8ByteLength(value) {
  let bytes = 0;
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code <= 0x7f) bytes += 1;
    else if (code <= 0x7ff) bytes += 2;
    else if (code >= 0xd800 && code <= 0xdbff && index + 1 < value.length && value.charCodeAt(index + 1) >= 0xdc00 && value.charCodeAt(index + 1) <= 0xdfff) {
      bytes += 4;
      index += 1;
    } else bytes += 3;
  }
  return bytes;
}
function httpUrl(value) {
  if (!nonEmpty(value) || /[\s\\]/.test(value)) return false;
  const match = /^(https?):\/\/([^/?#]+)(?:[/?#].*)?$/i.exec(value.trim());
  if (!match) return false;
  let authority = match[2];
  const userInfoEnd = authority.lastIndexOf('@');
  if (userInfoEnd >= 0) authority = authority.slice(userInfoEnd + 1);
  const hostMatch = /^(\[[0-9a-f:.]+\]|[^:]+)(?::(\d{1,5}))?$/i.exec(authority);
  return Boolean(hostMatch && hostMatch[1] && (!hostMatch[2] || Number(hostMatch[2]) <= 65535));
}
function validIntake(intake) {
  return isObject(intake)
    && nonEmpty(intake.organization_name)
    && httpUrl(intake.website)
    && /^[A-Z]{2}$/.test(intake.country || '')
    && nonEmpty(intake.current_challenge)
    && isObject(intake.research_window)
    && /^\d{4}-\d{2}-\d{2}$/.test(intake.research_window.start_date || '')
    && /^\d{4}-\d{2}-\d{2}$/.test(intake.research_window.end_date || '')
    && Array.isArray(intake.uploaded_document_refs)
    && intake.uploaded_document_refs.every(nonEmpty);
}
const correlationId = isObject(raw) && nonEmpty(raw.correlation_id) ? raw.correlation_id : generatedId('CORR');
const runId = isObject(raw) && nonEmpty(raw.run_id) ? raw.run_id : generatedId('RUN');
try {
  if (!isObject(raw)) throw new Error('invalid');
  if (utf8ByteLength(JSON.stringify(raw)) > MAX_BYTES) throw new Error('invalid');
  if (raw.contract_version !== CONTRACT_VERSION || raw.mode !== 'live') throw new Error('invalid');
