}

const child = items[0]?.json;
const request = $('VALIDATE__WEB_REQUEST').first().json;
const base = { contract_version: '1.0', correlation_id: request.correlation_id, run_id: request.run_id, demo: false };
function isObject(value) { return Boolean(value) && typeof value === 'object' && !Array.isArray(value); }
function nonEmpty(value) { return typeof value === 'string' && value.trim().length > 0; }
function validSource(source) { return isObject(source) && /^SRC-/.test(source.source_id || '') && nonEmpty(source.title) && nonEmpty(source.url) && typeof source.is_official === 'boolean'; }
function validEvidence(evidence) { return isObject(evidence) && /^EV-/.test(evidence.evidence_id || '') && nonEmpty(evidence.run_id) && nonEmpty(evidence.claim) && Array.isArray(evidence.source_ids) && Number.isFinite(evidence.confidence) && evidence.confidence >= 0 && evidence.confidence <= 1; }
function validFinding(finding) { return isObject(finding) && /^F-OPS-/.test(finding.finding_id || '') && finding.domain === 'operations_cx' && nonEmpty(finding.finding) && Array.isArray(finding.evidence_ids) && finding.evidence_ids.length > 0 && ['observed','inferred','hypothesis','unknown'].includes(finding.finding_type) && Number.isFinite(finding.confidence) && finding.confidence >= 0 && finding.confidence <= 1 && typeof finding.requires_validation === 'boolean' && (finding.validation_question === null || nonEmpty(finding.validation_question)); }
