  if (!isObject(child) || child.status !== 'completed' || child.demo !== false) throw new Error('invalid');
  const data = child.data;
  if (!isObject(data) || !Array.isArray(data.sources) || !Array.isArray(data.evidence) || !Array.isArray(data.findings) || !data.findings.length) throw new Error('invalid');
  if (!data.sources.every(validSource) || !data.evidence.every(validEvidence) || !data.findings.every(validFinding)) throw new Error('invalid');
  const sourceIds = new Set(data.sources.map(source => source.source_id));
  const evidenceIds = new Set(data.evidence.map(evidence => evidence.evidence_id));
  if (sourceIds.size !== data.sources.length || evidenceIds.size !== data.evidence.length) throw new Error('invalid');
  for (const evidence of data.evidence) for (const sourceId of evidence.source_ids) if (!sourceIds.has(sourceId)) throw new Error('invalid');
  for (const finding of data.findings) {
    for (const evidenceId of finding.evidence_ids) if (!evidenceIds.has(evidenceId)) throw new Error('invalid');
    if (finding.finding_type === 'observed' && (finding.requires_validation || finding.validation_question !== null)) throw new Error('invalid');
    if (finding.finding_type !== 'observed' && (!finding.requires_validation || !finding.validation_question)) throw new Error('invalid');
  }
  return [{ json: { valid: true, response: { ...base, ...child, demo: false } } }];
} catch {
  return [{ json: { valid: false, response: { ...base, status: 'error', message: 'We couldn\'t prepare the diagnostic. Try again or continue with the local demo.', error: { code: 'invalid_upstream_response' } } } }];
}

